<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,openProtected,type Member} from './api'
import './forum.css'
type Claim={point_id:number;finding:string;recommendation:string;refs:string[]}
type ReportContent={claims:Claim[];limitations:string;window:{start:string;end:string};basis_version:string;point_names:Record<number,string>;metrics:{id:number;name:string;mastery:string|null;sample_size:number}[];evidence:Record<string,{attempt_id:number;question_id:number;score:string;maximum:string;grade_revision:number}>}
type Report={id:number;student_id:number;student_name:string;status:string;phase:string;revision:number;current_version:number;stale:boolean;error:string;model:string;skill:string;window:{start:string;end:string};version:null|{number:number;content:ReportContent;content_hash:string;html_url:string;pdf_url:string}}
const props=defineProps<{courseId:number;isTeacher:boolean}>()
const reports=ref<Report[]>([]),next=ref<number|null>(null),students=ref<Member[]>([]),student=ref(''),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),config=ref({enabled:true,revision:0})
const drafts=ref<Record<number,Claim[]>>({}),checks=ref<Record<number,number[]>>({}),reasons=ref<Record<number,string>>({})
const histories=ref<Record<number,{items:any[];next_page:number|null}>>({})
const start=ref(new Date(Date.now()-90*86400000).toISOString().slice(0,10)),end=ref(new Date(Date.now()+86400000).toISOString().slice(0,10))
const labels:Record<string,string>={queued:'排队中',running:'生成中',draft:'待教师复核',published:'已发布',cancelled:'已取消',failed:'失败',read_evidence:'读取授权证据',generate_findings:'生成带证据观察',render_exports:'制作同版HTML/PDF',awaiting_review:'待逐条复核',reviewed:'已复核，可发布'}
function init(p:Report){drafts.value[p.id]=p.version?.content.claims.map((c:Claim)=>({...c,refs:[...c.refs]}))||[];checks.value[p.id]=[];reasons.value[p.id]=''}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(page=1){const d=await api<{items:Report[];next_page:number|null}>(`courses/${props.courseId}/diagnostic-reports/?page=${page}`);reports.value=page===1?d.items:[...reports.value,...d.items];next.value=d.next_page;for(const r of d.items)init(r)}
async function refresh(){await load();if(props.isTeacher)config.value=await api(`courses/${props.courseId}/diagnostic-settings/`)}
function update(p:Report){const reason=reasons.value[p.id];reports.value=reports.value.map(old=>old.id===p.id?p:old);init(p);if(p.phase==='reviewed')reasons.value[p.id]=reason}
function dirty(p:Report){return JSON.stringify(drafts.value[p.id])!==JSON.stringify(p.version?.content.claims||[])}
async function create(){await run(async()=>{const p=await api<Report>(`courses/${props.courseId}/diagnostic-reports/`,'POST',{student_id:Number(student.value),start:new Date(start.value+'T00:00:00Z').toISOString(),end:new Date(end.value+'T00:00:00Z').toISOString()});reports.value.unshift(p);init(p);notice.value='诊断任务已保存。稍后刷新查看草稿；不会自动发布。'})}
async function toggle(){await run(async()=>{config.value=await api(`courses/${props.courseId}/diagnostic-settings/`,'PUT',{enabled:!config.value.enabled,expected_revision:config.value.revision});notice.value=config.value.enabled?'已启用诊断技能':'已停用诊断技能，运行任务结果将拒绝进入复核'})}
async function action(p:Report,command:string){await run(async()=>{const result=await api<Report>(`diagnostic-reports/${p.id}/action/`,'POST',{action:command,expected_revision:p.revision,reason:reasons.value[p.id],checked_point_ids:checks.value[p.id]});update(result);notice.value=command==='publish'?'已向该学生发布同版HTML/PDF报告':command==='withdraw'?'已撤回，学生无法继续访问':'操作已记录'})}
async function revise(p:Report){await run(async()=>{update(await api<Report>(`diagnostic-reports/${p.id}/revise/`,'POST',{expected_revision:p.revision,claims:drafts.value[p.id],reason:reasons.value[p.id]}));notice.value='已保存新草稿版本，HTML/PDF同步更新，需重新复核'})}
async function history(p:Report,page=1){await run(async()=>{const d=await api<{items:any[];next_page:number|null}>(`diagnostic-reports/${p.id}/versions/?page=${page}`);histories.value[p.id]={items:page===1?d.items:[...histories.value[p.id].items,...d.items],next_page:d.next_page}})}
function point(p:Report,id:number){return p.version?.content.point_names[id]||'#'+id}
onMounted(async()=>{await run(async()=>{await refresh();if(props.isTeacher){students.value=(await api<Member[]>(`courses/${props.courseId}/members/`)).filter(m=>m.role==='student');student.value=students.value.length?String(students.value[0].id):''}});loading.value=false})
</script>
<template>
<section class="forum-workspace diagnostic-workspace"><div class="section-head"><div><h2>学情诊断报告</h2><p>报告建议不改变正式成绩。教师逐条复核并发布后，学生才能查看本人报告。</p></div><button class="secondary" :disabled="busy" @click="run(refresh)">刷新报告</button></div><p v-if="loading" role="status">正在加载诊断报告…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="isTeacher"><article class="forum-card"><h3>学情诊断技能</h3><p>{{config.enabled?'已启用':'已停用'}} · learning-diagnosis@1.0.0</p><button class="secondary" :disabled="busy" @click="toggle">{{config.enabled?'停用诊断技能':'启用诊断技能'}}</button></article><form class="forum-card diagnostic-form" @submit.prevent="create"><label>目标学生<select v-model="student" required><option value="">请选择学生</option><option v-for="s in students" :key="s.id" :value="String(s.id)">{{s.name||'学生 #'+s.id}}</option></select></label><label>开始日期（UTC）<input v-model="start" type="date" required></label><label>结束日期（UTC，不含当日）<input v-model="end" type="date" required></label><p>仅使用目标学生的已公开正式评分、已批准图谱和当前成绩策略。答案公开前不分析作答文本，无评分证据不作诊断。</p><button class="primary" :disabled="busy||!student||!config.enabled">生成诊断草稿</button></form></template>
<p v-if="!loading&&!reports.length&&!error">{{isTeacher?'暂无本人发起的诊断任务。':'暂无向本人发布的有效诊断报告。'}}</p>
<article v-for="p in reports" :key="p.id" class="forum-card"><h3>报告 #{{p.id}} · {{p.student_name}} · {{labels[p.status]||p.status}}</h3><p v-if="p.status==='running'">当前步骤：{{labels[p.phase]||p.phase}}，可取消任务。</p><p v-if="p.status==='queued'">已进入持久化队列，稍后刷新查看。</p><p v-if="p.error" class="error" role="alert">{{p.error}}</p><p v-if="p.stale" class="error" role="alert">评分、作答公开状态、图谱或资料已变化。旧说明和导出已隐藏，请重新生成。</p>
<template v-if="p.version"><p>报告版本 {{p.version.number}} · {{p.skill}} · {{p.model||'无评分证据，未调用模型'}} · {{labels[p.phase]||p.phase}}</p><p>{{p.version.content.limitations}}</p><div class="diagnostic-actions"><button class="secondary" :disabled="busy" @click="run(()=>openProtected(p.version!.html_url))">查看同版 HTML</button><button class="secondary" :disabled="busy" @click="run(()=>openProtected(p.version!.pdf_url))">查看同版 PDF</button></div><details><summary>固定窗口、数据版本与统计</summary><p>UTC：{{p.version.content.window.start}} 至 {{p.version.content.window.end}}（结束不含）</p><p>数据版本 {{p.version.content.basis_version}}</p><p>内容版本 {{p.version.content_hash}}</p><p v-for="m in p.version.content.metrics" :key="m.id">{{m.name}} · {{m.mastery===null?'未知':(Number(m.mastery)*100).toFixed(1)+'%'}} · {{m.sample_size}} 道有效题</p></details>
<p v-if="!p.version.content.claims.length">暂无有效评分证据，不作学习诊断；可先复习资料并完成测验。</p>
<ol class="diagnostic-claims"><li v-for="(c,i) in p.version.content.claims" :key="c.point_id"><h4>{{point(p,c.point_id)}}</h4><p class="diagnostic-text">学习观察：{{c.finding}}</p><p class="diagnostic-text">复习建议：{{c.recommendation}}</p><details><summary>回查正式评分证据</summary><p v-for="ref in c.refs" :key="ref">{{ref}} · 答卷 #{{p.version.content.evidence[ref]?.attempt_id}} · 题 #{{p.version.content.evidence[ref]?.question_id}} · {{p.version.content.evidence[ref]?.score}}/{{p.version.content.evidence[ref]?.maximum}} · 评分 v{{p.version.content.evidence[ref]?.grade_revision}}</p></details>
<template v-if="isTeacher&&p.status==='draft'&&!p.stale"><details><summary>修订本条观察与建议</summary><label>学习观察<textarea v-model="drafts[p.id][i].finding" maxlength="1200" rows="4"/></label><label>复习建议<textarea v-model="drafts[p.id][i].recommendation" maxlength="1200" rows="4"/></label><p>保留本条真实评分引用；保存修订会创建新版本并重新复核。</p></details><label class="diagnostic-check"><input v-model="checks[p.id]" type="checkbox" :value="c.point_id">已核对本条观察、建议和引用</label></template></li></ol>
<template v-if="isTeacher&&p.status==='draft'&&!p.stale"><label>复核或修订理由<textarea v-model="reasons[p.id]" maxlength="500" rows="2"/></label><div class="diagnostic-actions"><button class="secondary" :disabled="busy||!reasons[p.id]" @click="revise(p)">保存修订为新版本</button><button class="primary" :disabled="busy||dirty(p)||!reasons[p.id]||checks[p.id]?.length!==p.version.content.claims.length" @click="action(p,'review')">确认逐条复核</button><button v-if="p.phase==='reviewed'" class="primary" :disabled="busy||dirty(p)||!reasons[p.id]" @click="action(p,'publish')">发布给该学生</button></div><p>先查看证据再复核；有未保存修订时不能复核或发布，请先保存新版本。发布不会修改成绩。</p></template></template>
<template v-if="isTeacher&&p.current_version"><button class="secondary" :disabled="busy" @click="history(p)">查看报告版本历史</button><p>历史版本可能含待纠正的模型文字，仅供回查，不代表已发布结论。</p><div v-if="histories[p.id]"><p v-for="v in histories[p.id].items" :key="v.number">版本 {{v.number}} · {{v.reason}} <button v-if="v.html_url" class="secondary" @click="run(()=>openProtected(v.html_url))">查看历史 HTML</button><button v-if="v.pdf_url" class="secondary" @click="run(()=>openProtected(v.pdf_url))">查看历史 PDF</button></p><button v-if="histories[p.id].next_page" class="secondary" :disabled="busy" @click="history(p,histories[p.id].next_page!)">更早版本</button></div></template><button v-if="isTeacher&&['queued','running','draft'].includes(p.status)" class="secondary" :disabled="busy" @click="action(p,'cancel')">取消此诊断任务</button><button v-if="isTeacher&&p.status==='published'" class="secondary" :disabled="busy" @click="action(p,'withdraw')">撤回报告</button></article>
<button v-if="next" class="secondary" :disabled="busy" @click="run(()=>load(next!))">加载更早报告</button></section>
</template>
<style scoped>
.diagnostic-workspace{min-width:0;overflow-wrap:anywhere}.diagnostic-form{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.diagnostic-form label{display:grid;gap:6px;flex:1 1 180px;min-width:0}.diagnostic-form p{flex-basis:100%}.diagnostic-form input,.diagnostic-form select{width:100%;min-width:0}.diagnostic-actions{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.diagnostic-claims{padding-left:24px}.diagnostic-claims>li{border-bottom:1px solid #ddd;padding:12px 0}.diagnostic-text{white-space:pre-wrap}.diagnostic-workspace textarea{display:block;width:100%;box-sizing:border-box;margin:8px 0}.diagnostic-check{display:flex;align-items:center;gap:8px;margin:12px 0}.diagnostic-check input{width:auto}
</style>
